using System;using System.Collections.Generic;
public class BaseUnlockableAsset {public string id="",achievement_id="";public bool unlocked_with_achievement=true,needs_to_be_explored=true;public bool isTemplateAsset(){return id.StartsWith("$");}}
public class ItemAsset:BaseUnlockableAsset {public bool mod_can_be_given;}public class EquipmentAsset:ItemAsset {}public class ActorTrait:BaseUnlockableAsset {public bool can_be_given,can_be_removed;}public class SubspeciesTrait:ActorTrait {}public class ActorAsset:BaseUnlockableAsset {public bool is_boat,can_receive_traits,can_edit_traits,can_be_inspected;}public class CultureTrait:BaseUnlockableAsset{}public class LanguageTrait:BaseUnlockableAsset{}public class ClanTrait:BaseUnlockableAsset{}public class KingdomTrait:BaseUnlockableAsset{}public class ReligionTrait:BaseUnlockableAsset{}public class OtherAsset:BaseUnlockableAsset{}
public class Library<T> {public List<T> list=new List<T>();}public class ItemLibrary:Library<EquipmentAsset> {public List<EquipmentAsset> pot_weapon_assets_all=new List<EquipmentAsset>(),pot_weapon_assets_unlocked=new List<EquipmentAsset>();public Dictionary<string,List<EquipmentAsset>> pot_equipment_by_groups_all=new Dictionary<string,List<EquipmentAsset>>(),pot_equipment_by_groups_unlocked=new Dictionary<string,List<EquipmentAsset>>();}
public class GameProgressData {public HashSet<string> unlocked_traits_culture,unlocked_traits_language,unlocked_traits_clan,unlocked_traits_kingdom,unlocked_traits_religion;public HashSet<string> unlocked_actors=new HashSet<string>(),unlocked_traits_subspecies=new HashSet<string>(),unlocked_traits_actor=new HashSet<string>(),unlocked_equipment=new HashSet<string>(),achievements=new HashSet<string>();}public class GameProgress {public static GameProgress instance;internal GameProgressData data=new GameProgressData();}public static class AssetManager {public static Library<CultureTrait> culture_traits;public static Library<LanguageTrait> language_traits;public static Library<ClanTrait> clan_traits;public static Library<KingdomTrait> kingdoms_traits;public static Library<ReligionTrait> religion_traits;public static Library<ActorAsset> actor_library;public static Library<SubspeciesTrait> subspecies_traits;public static Library<ActorTrait> traits;public static ItemLibrary items;public static Library<ItemAsset> items_modifiers;}
class UnlockTests {
 static int count;static void Check(bool b,string label){if(!b)throw new Exception(label);count++;}
 static void Main(){NativeUnlocks.Apply();Check(true,"cold initialization without managers");var weapon=new EquipmentAsset{id="shotgun",achievement_id="locked"};var armor=new EquipmentAsset{id="armor_adamantine"};var trait=new ActorTrait{id="immortal"};var mod=new ItemAsset{id="modifier"};AssetManager.items=new ItemLibrary();AssetManager.items.list.AddRange(new[]{weapon,armor});AssetManager.items.pot_weapon_assets_all.Add(weapon);AssetManager.items.pot_equipment_by_groups_all["armor"]=new List<EquipmentAsset>{armor};AssetManager.traits=new Library<ActorTrait>();AssetManager.traits.list.Add(trait);AssetManager.items_modifiers=new Library<ItemAsset>();AssetManager.items_modifiers.list.Add(mod);var animal=new ActorAsset{id="wolf"};var monster=new ActorAsset{id="demon"};var boat=new ActorAsset{id="boat",is_boat=true};var template=new ActorAsset{id="$animal"};var gene=new SubspeciesTrait{id="magic_blood"};AssetManager.actor_library=new Library<ActorAsset>();AssetManager.actor_library.list.AddRange(new[]{animal,monster,boat,template});AssetManager.subspecies_traits=new Library<SubspeciesTrait>();AssetManager.subspecies_traits.list.Add(gene);GameProgress.instance=new GameProgress();NativeUnlocks.Apply();Check(weapon.unlocked_with_achievement&&GameProgress.instance.data.unlocked_equipment.Count==0,"partial startup does not mutate native libraries or progress");NativeUnlocks.AssetsReady();NativeUnlocks.EquipmentPools(AssetManager.items);
 Check(NativeUnlocks.Target(weapon)&&NativeUnlocks.Target(trait)&&NativeUnlocks.Target(mod)&&!NativeUnlocks.Target(new OtherAsset()),"availability limited to equipment and personal traits");Check(!weapon.unlocked_with_achievement&&!weapon.needs_to_be_explored&&weapon.achievement_id=="","equipment achievement and exploration locks removed");Check(trait.can_be_given&&trait.can_be_removed&&!trait.needs_to_be_explored,"all personal traits editable");Check(mod.mod_can_be_given&&!mod.unlocked_with_achievement,"item modifiers editable");Check(GameProgress.instance.data.unlocked_traits_actor.Contains("immortal")&&GameProgress.instance.data.unlocked_equipment.Count==2,"native unlock collections populated");Check(GameProgress.instance.data.achievements.Count==0,"achievements not fabricated");Check(AssetManager.items.pot_weapon_assets_unlocked.Contains(weapon)&&AssetManager.items.pot_equipment_by_groups_unlocked["armor"].Contains(armor),"native unlocked item pools complete");NativeUnlocks.EquipmentPools(AssetManager.items);Check(AssetManager.items.pot_weapon_assets_unlocked.Count==1&&GameProgress.instance.data.unlocked_equipment.Count==2,"unlocking is idempotent");Check(animal.can_receive_traits&&animal.can_edit_traits&&animal.can_be_inspected&&monster.can_edit_traits,"animals and monsters inspectable and traits editable");Check(!boat.can_edit_traits&&!template.can_edit_traits,"boats and templates not converted to creatures");Check(GameProgress.instance.data.unlocked_actors.Count==3&&!GameProgress.instance.data.unlocked_actors.Contains("$animal"),"real creature catalog unlocked without templates");Check(gene.can_be_given&&gene.can_be_removed&&GameProgress.instance.data.unlocked_traits_subspecies.Contains(gene.id),"subspecies traits unlocked");Check(NativeUnlocks.Target(animal)&&NativeUnlocks.Target(monster)&&NativeUnlocks.Target(gene),"creature and subspecies native gates covered");AssetManager.culture_traits=new Library<CultureTrait>();AssetManager.culture_traits.list.Add(new CultureTrait{id="roads"});AssetManager.language_traits=new Library<LanguageTrait>();AssetManager.language_traits.list.Add(new LanguageTrait{id="test_language"});AssetManager.clan_traits=new Library<ClanTrait>();AssetManager.clan_traits.list.Add(new ClanTrait{id="test_clan"});AssetManager.kingdoms_traits=new Library<KingdomTrait>();AssetManager.kingdoms_traits.list.Add(new KingdomTrait{id="test_kingdom"});AssetManager.religion_traits=new Library<ReligionTrait>();AssetManager.religion_traits.list.Add(new ReligionTrait{id="test_religion"});NativeUnlocks.Apply();var p=GameProgress.instance.data;Check(p.unlocked_traits_culture.Contains("roads")&&p.unlocked_traits_language.Contains("test_language")&&p.unlocked_traits_clan.Contains("test_clan")&&p.unlocked_traits_kingdom.Contains("test_kingdom")&&p.unlocked_traits_religion.Contains("test_religion"),"all five independent organization trait collections initialized and filled");Check(NativeUnlocks.Target(new CultureTrait{id="test"})&&NativeUnlocks.Target(new LanguageTrait{id="test"})&&NativeUnlocks.Target(new ClanTrait{id="test"})&&NativeUnlocks.Target(new KingdomTrait{id="test"})&&NativeUnlocks.Target(new ReligionTrait{id="test"}),"organization trait native availability gates unlocked");Check(!NativeUnlocks.Target(template),"template availability not forced");Check(!NativeUnlocks.Target(null)&&!NativeUnlocks.Target(new ActorTrait{id=null})&&!NativeUnlocks.Target(new ActorTrait{id="_internal"}),"null and incomplete native assets are safe");var keep=AssetManager.traits.list;AssetManager.traits.list=null;AssetManager.actor_library.list.Add(null);AssetManager.items.list.Add(null);AssetManager.subspecies_traits.list.Add(new SubspeciesTrait{id=null});NativeUnlocks.Apply();Check(NativeUnlocks.LastError=="","missing lists and asset IDs do not interrupt startup");AssetManager.traits.list=keep;var data=GameProgress.instance.data;GameProgress.instance.data=null;NativeUnlocks.Apply();Check(NativeUnlocks.LastError=="","assets can finish before progress data exists");GameProgress.instance.data=data;var all=AssetManager.items.pot_weapon_assets_all;AssetManager.items.pot_weapon_assets_all=null;NativeUnlocks.EquipmentPools(AssetManager.items);Check(NativeUnlocks.LastError=="","unfinished native equipment pools are safe");AssetManager.items.pot_weapon_assets_all=all;NativeUnlocks.Apply();Check(data.unlocked_equipment.Contains("shotgun"),"late progress load receives unlocks after initialization");Console.WriteLine(count+" unlock checks passed");}
}

namespace UnityEngine {public static class Debug {public static void LogWarning(object message){Console.WriteLine(message);}}}
